def attempt(issues, *, full=()):
    return cli._FailedEncodeAttempt(
        SimpleNamespace(),
        "Generated RuleSpec failed CI validation",
        None,
        issues,
        len(full or issues),
        full,
    )


def test_actual_compile_failure_cannot_outrank_compiled_source_candidate():
    broken = attempt(ACTUAL_ISSUES, full=ACTUAL_ISSUES)
    # Controlled comparison, not a reconstruction of lost hosted attempt scores.
    compiled = attempt(tuple("source obligation" for _ in range(34)))
    assert cli._best_validation_retry_attempt([compiled, broken]) is compiled


@pytest.mark.parametrize(
    "diagnostic",
    [
        "policies/example.yaml: compile: Axiom rules engine compile failed: invalid formula",
        "policies/example.yaml: ci: Axiom rules engine compile failed: invalid formula",
    ],
)
def test_compile_failure_in_full_issues_not_only_truncated_feedback(diagnostic):
    broken = attempt(("source obligation",), full=(diagnostic,))
    compiled = attempt(("source one", "source two"))
    assert cli._best_validation_retry_attempt([compiled, broken]) is compiled


@pytest.mark.parametrize(
    "diagnostic",
    [
        "source prose says compile: Axiom rules engine compile failed: example",
        "policies/example.yaml: ci: source quotation: Axiom rules engine compile failed: example",
        "policies/example.yaml: ci: [source-proof] cite compile: operation",
    ],
)
def test_noncompile_prose_preserves_existing_order(diagnostic):
    fewer = attempt((diagnostic,))
    more = attempt(("one", "two"))
    assert cli._best_validation_retry_attempt([more, fewer]) is fewer
